//
// ```javascript
// if (hasParentNode(node => node.type === schema.nodes.table)(selection)) {
//   // ....
// }
// ```
export const hasParentNode = (predicate: Predicate) => (selection: Selection) => {
  return !!findParentNode(predicate)(selection);
};

